/*
 * Bring the real curriculum into the app.
 *
 * Source: the meyilnamalar repo — `generalized/<grade>/<subject>.json`, the
 * condensed themes (temalar) for grades 1–12 of the Turkmen school programme.
 * That repo is generated from a spreadsheet and regenerated by its own scripts,
 * so this is a one-way import: never hand-edit `src/data/curriculum.json`,
 * re-run this instead.
 *
 *   node scripts/import-curriculum.mjs [path-to-meyilnamalar]
 *
 * What is kept per theme: `[name, hours]`, plus — for the themes that already
 * have teaching material — three more numbers: `[name, hours, readMinutes,
 * testCount, hasApp]`. Those decide the *kind* of a lesson in the app: a theme
 * with a mini-app under `apps/` is an interactive lesson, a theme with a
 * `test_bank` and no app is a test, a theme with written content is a reading
 * lesson. Nothing about a lesson's form is invented any more.
 *
 * What is dropped: `related` (the original per-lesson titles a theme was merged
 * from) and quarter numbers — the app shows a path of themes, and a payload it
 * does not read is weight in every user's download.
 *
 * The lesson *pages* come from the same import:
 *   src/data/lessons/<grade>-<slug>.json   the written lesson, one file per
 *                                          subject-grade, loaded on demand
 *   public/lesson-apps/<grade>/<slug>/…    the interactive mini-apps, served
 *                                          as they are and never bundled
 */

import { readFileSync, writeFileSync, readdirSync, existsSync, mkdirSync, rmSync, cpSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const SRC = process.argv[2] ?? '/Users/agoyli/code/experiments/meyilnamalar';
const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const OUT = join(ROOT, 'src', 'data', 'curriculum.json');
const LESSONS = join(ROOT, 'src', 'data', 'lessons');
const APPS = join(ROOT, 'public', 'lesson-apps');

if (!existsSync(join(SRC, 'generalized'))) {
  console.error(`No generalized/ under ${SRC}`);
  process.exit(1);
}

const subjects = JSON.parse(readFileSync(join(SRC, 'subjects.json'), 'utf8'));
const bySlug = new Map(subjects.map((s) => [s.slug, s]));

/*
 * The material a theme has, from the two places that hold it: `content/` (the
 * written lesson, its reading time and its test bank) and `apps/` (one
 * interactive mini-app per theme, filed as `<theme_no>-<slug>.html`). Both are
 * keyed by `theme_no`, which is the theme's 1-based position in `generalized/`.
 */
/** theme_no → mini-app filename, for one subject-grade */
const appsFor = (grade, slug) => {
  const byNo = new Map();
  const dir = join(SRC, 'apps', String(grade), slug);
  if (!existsSync(dir)) return byNo;
  for (const file of readdirSync(dir).filter((f) => f.endsWith('.html'))) {
    byNo.set(Number(file.slice(0, file.indexOf('-'))), file);
  }
  return byNo;
};

const materialFor = (grade, slug) => {
  const byNo = new Map();
  const contentFile = join(SRC, 'content', String(grade), `${slug}.json`);
  if (existsSync(contentFile)) {
    for (const t of JSON.parse(readFileSync(contentFile, 'utf8')).themes ?? []) {
      byNo.set(t.theme_no, {
        readMinutes: t.read_minutes ?? 0,
        testCount: (t.test_bank ?? []).length,
        hasApp: 0,
      });
    }
  }
  for (const no of appsFor(grade, slug).keys()) {
    const m = byNo.get(no) ?? { readMinutes: 0, testCount: 0, hasApp: 0 };
    byNo.set(no, { ...m, hasApp: 1 });
  }
  return byNo;
};

/* grade dirs are named 1..12 — read them in numeric order, not lexical */
const grades = readdirSync(join(SRC, 'generalized'))
  .filter((d) => /^\d+$/.test(d))
  .sort((a, b) => Number(a) - Number(b));

/** slug → { slug, name, grades: [{ grade, themes: [[name, hours], …] }] } */
const out = new Map();

for (const g of grades) {
  const dir = join(SRC, 'generalized', g);
  for (const file of readdirSync(dir).filter((f) => f.endsWith('.json')).sort()) {
    const slug = file.slice(0, -5);
    const doc = JSON.parse(readFileSync(join(dir, file), 'utf8'));
    const material = materialFor(Number(g), slug);
    const themes = (doc.themes ?? [])
      .map((t, i) => {
        const m = material.get(i + 1);
        const base = [t.name.trim(), t.hours ?? 0];
        return m ? [...base, m.readMinutes, m.testCount, m.hasApp] : base;
      })
      .filter(([name]) => name.length > 0);
    if (themes.length === 0) continue;

    if (!out.has(slug)) {
      out.set(slug, {
        slug,
        /* the master list's name wins — the per-grade files abbreviate a few
           ("T-nyň taryhy"), and a subject must read the same in every grade */
        name: bySlug.get(slug)?.name ?? doc.subject,
        grades: [],
      });
    }
    out.get(slug).grades.push({ grade: Number(g), themes });
  }
}

const list = [...out.values()].sort((a, b) => a.name.localeCompare(b.name, 'tk'));
writeFileSync(OUT, `${JSON.stringify(list)}\n`, 'utf8');

/*
 * The lesson pages.
 *
 * One file per subject-grade, named so the app can ask for exactly the one it
 * needs — `7-fizika.json` — and nothing else. The whole set is 1.7 MB, which is
 * a page nobody opens for every reader who opens one, so these are never
 * bundled with the app: Vite splits them and the lesson screen fetches its own.
 *
 * The only reshaping is the answers: the source keys options by letter
 * (A/B/Ç/D) and names the right one by letter too, which the UI would have to
 * undo on every render. They arrive here as a list and an index.
 */
const ANSWER = (q) => Object.keys(q.options).indexOf(q.answer);

rmSync(LESSONS, { recursive: true, force: true });
mkdirSync(LESSONS, { recursive: true });

let files = 0;
let lessons = 0;
for (const g of grades) {
  const dir = join(SRC, 'content', g);
  if (!existsSync(dir)) continue;
  for (const file of readdirSync(dir).filter((f) => f.endsWith('.json')).sort()) {
    const doc = JSON.parse(readFileSync(join(dir, file), 'utf8'));
    const apps = appsFor(Number(g), file.slice(0, -5));
    const themes = (doc.themes ?? []).map((t) => ({
      no: t.theme_no,
      /* the mini-app's own filename — the app links to it, it does not guess it */
      app: apps.get(t.theme_no) ?? '',
      title: t.theme,
      minutes: t.read_minutes ?? 0,
      hook: t.hook ?? '',
      summary: t.summary ?? '',
      steps: t.steps ?? [],
      concepts: t.key_concepts ?? [],
      formulas: t.formulas ?? [],
      examples: t.examples ?? [],
      mustKnow: t.must_know ?? [],
      examPoints: t.exam_points ?? [],
      selfCheck: (t.self_check ?? []).map((q) => ({ q: q.question, a: q.answer })),
      test: (t.test_bank ?? []).map((q) => ({
        q: q.question,
        options: Object.values(q.options),
        correct: ANSWER(q),
      })),
      /* the question the lesson's own author would start the AI helper with */
      aiStarter: t.ai_starter ?? '',
    }));
    if (themes.length === 0) continue;
    writeFileSync(join(LESSONS, `${g}-${file}`), `${JSON.stringify(themes)}\n`, 'utf8');
    files += 1;
    lessons += themes.length;
  }
}

/* The mini-apps are copied, not read: each is a finished self-contained page
   that shares one stylesheet two directories up, so the tree is kept as it is
   and served from `public/` untouched. */
rmSync(APPS, { recursive: true, force: true });
cpSync(join(SRC, 'apps'), APPS, {
  recursive: true,
  filter: (src) => !src.endsWith('index.html'),
});

const themes = list.flatMap((s) => s.grades.flatMap((g) => g.themes));
const ready = themes.filter((t) => t.length > 2).length;
console.log(`${list.length} subjects, ${themes.length} themes (${ready} with material) → ${OUT}`);
console.log(`${(readFileSync(OUT).length / 1024).toFixed(0)} KB`);
console.log(`${lessons} lesson pages in ${files} files → ${LESSONS}`);
console.log(`mini-apps → ${APPS}`);
